-- paperclip:migration-safety-ignore large-create-index-not-concurrently: The migration runner wraps each migration in a transaction, so CONCURRENTLY is unavailable. These partial indexes cover only runs that registered a secret redaction, a small fraction of heartbeat_runs, and are additive: an image that predates them ignores them. Each index build scans heartbeat_runs separately (two scans); the transaction holds a SHARE lock on the table through both builds and the commit, so reads continue but concurrent writes to heartbeat_runs wait for that time.
CREATE INDEX IF NOT EXISTS "heartbeat_runs_company_ctx_issue_redaction_idx" ON "heartbeat_runs" USING btree ("company_id",("context_snapshot" ->> 'issueId')) WHERE "heartbeat_runs"."context_snapshot" ? 'paperclipSecretRedactions';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "heartbeat_runs_company_ctx_pcissue_redaction_idx" ON "heartbeat_runs" USING btree ("company_id",("context_snapshot" -> 'paperclipIssue' ->> 'id')) WHERE "heartbeat_runs"."context_snapshot" ? 'paperclipSecretRedactions';
